/** A resolved color: its canonical CSS string and sRGB channels 0–255 with alpha 0–1. */
export interface PaletteColor { readonly css: string; readonly rgba: readonly [r: number, g: number, b: number, a: number] }
/** Every color token of one context. */
export type Palette = { readonly [token in ColorToken]: PaletteColor };

export const themes = ["light", "dark"] as const;
export const brands = [] as const;
export const contexts = ["light", "dark"] as const satisfies readonly PaletteContext[];
export const defaultContext: PaletteContext = "light";
/** The theme each OS color scheme selects on a root without data-theme (followSystemTheme), or null. */
export const systemThemes: { readonly light: (typeof themes)[number]; readonly dark: (typeof themes)[number] } | null = { light: "light", dark: "dark" };

/** A declared theme. */
export type Theme = (typeof themes)[number];
/** Each declared theme's color scheme. */
export const themeSchemes = { light: "light", dark: "dark" } as const satisfies { readonly [theme in Theme]: "light" | "dark" };

/** A runtime value per declared theme (complete CSS values, such as colors from data) as one
 * expression that follows the nearest data-theme, like a token's halves. Use it for inline
 * styles and inline custom properties; never light-dark(). */
export function themed(values: { readonly [theme in Theme]: string }): string {
  return `var(--ads-if-light, ${values.light})var(--ads-if-dark, ${values.dark})`;
}

/** themed() from a light and a dark value: each declared theme takes the value of its color scheme. */
export function themedByScheme(values: { readonly light: string; readonly dark: string }): string {
  return `var(--ads-if-light, ${values.light})var(--ads-if-dark, ${values.dark})`;
}

